RUBRIC = {
    '开场与身份说明': 5,
    '需求识别与回应完整性': 20,
    '信息准确性与风险控制': 15,
    '问题解决与承诺闭环': 15,
    '服务态度与专业措辞': 15,
    '打断与通话节奏': 10,
    '客户情绪与服务修复': 10,
    '结束语与待办确认': 10,
}


def summarize(scores):
    # 返回 {'total': ..., 'missing': ..., 'worst': ...}
    return {}

print(summarize(RUBRIC))

