for _cut in (0.4, 0.6, 0.79, 0.8, 0.81, 0.95):
    _scores = {}
    for _k, _max in RUBRIC.items():
        _scores[_k] = round(_max * 0.95, 2)
    _scores['打断与通话节奏'] = round(10 * _cut, 2)
    _out = summarize(_scores)
    _want = 10 if 10 * _cut <= 8 else 'none'
    assert _out['worst'] == _want, ('被改动的这一项要么独苗不合格，要么完全不计入', _cut, _out)
    assert abs(_out['total'] - sum(_scores.values())) < 1e-9, (_cut, _out)
    assert _out['missing'] == 'incomplete', (_cut, _out)
for _cut in (0.79, 0.8, 0.81, 0.95):
    _scores = {k: round(v * _cut, 2) for k, v in RUBRIC.items()}
    _out = summarize(_scores)
    if _cut > 0.8:
        assert _out['worst'] == 'none', (_cut, _out)
    else:
        _lowest = None
        _full = 'none'
        for _k, _max in RUBRIC.items():
            _r = _scores[_k] / _max
            if _lowest is None or _r < _lowest:
                _lowest = _r
                _full = _max
        assert _out['worst'] == _full, ('整体同率时报得分率最低那一项的满分', _cut, _out)
    assert _out['missing'] == 'incomplete', ('打折就凑不满 100 分', _cut, _out)
